import React, { useState, useEffect } from 'react';
import { Heart, Zap, Trophy, MapPin, Diamond, Rocket, ArrowUpCircle, Shield, Activity, PlusCircle, Play, Cpu, ChevronRight } from 'lucide-react';
import { useStore } from '../../store';
import { GameStatus, GEMINI_COLORS, ShopItem, RUN_SPEED_BASE } from '../../types';
import { audio } from '../System/Audio';

const SHOP_ITEMS: ShopItem[] = [
    {
        id: 'DOUBLE_JUMP',
        name: 'FLIGHT DRIVE',
        description: 'Initiate secondary vertical thrust mid-air.',
        cost: 1000,
        icon: ArrowUpCircle,
        oneTime: true
    },
    {
        id: 'MAX_LIFE',
        name: 'CORE UPGRADE',
        description: 'Expand physical integrity systems permanently.',
        cost: 1500,
        icon: Activity
    },
    {
        id: 'HEAL',
        name: 'NANOBOT REPAIR',
        description: 'Immediate restoration of one life unit.',
        cost: 1000,
        icon: PlusCircle
    },
    {
        id: 'IMMORTAL',
        name: 'PHASE SHIFT',
        description: 'Briefly become untargetable by cosmic matter.',
        cost: 3000,
        icon: Shield,
        oneTime: true
    }
];

const ShopScreen: React.FC = () => {
    const { score, buyItem, closeShop, hasDoubleJump, hasImmortality } = useStore();
    const [items, setItems] = useState<ShopItem[]>([]);

    useEffect(() => {
        let pool = SHOP_ITEMS.filter(item => {
            if (item.id === 'DOUBLE_JUMP' && hasDoubleJump) return false;
            if (item.id === 'IMMORTAL' && hasImmortality) return false;
            return true;
        });
        pool = pool.sort(() => 0.5 - Math.random());
        setItems(pool.slice(0, 3));
    }, []);

    return (
        <div className="absolute inset-0 bg-[#050011]/95 z-[100] text-white pointer-events-auto backdrop-blur-xl overflow-y-auto font-cyber">
             <div className="flex flex-col items-center justify-center min-h-full py-8 px-4">
                 <div className="flex items-center space-x-3 mb-2">
                    <Cpu className="text-cyan-400 w-8 h-8 animate-pulse" />
                    <h2 className="text-3xl md:text-5xl font-black text-white tracking-tighter uppercase italic">TECH UPGRADE</h2>
                 </div>

                 <div className="h-1 w-24 bg-cyan-500 mb-8 rounded-full shadow-[0_0_10px_cyan]"></div>

                 <div className="flex items-center bg-white/5 px-6 py-2 rounded-full border border-white/10 text-yellow-400 mb-10">
                     <span className="text-xs mr-3 opacity-60">BIT-CREDITS:</span>
                     <span className="text-2xl font-bold">{score.toLocaleString()}</span>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full mb-12">
                     {items.map(item => {
                         const Icon = item.icon;
                         const canAfford = score >= item.cost;
                         return (
                             <div key={item.id} className="group relative bg-gray-900/40 border border-white/10 p-8 rounded-2xl flex flex-col items-center text-center hover:border-cyan-400/50 hover:bg-white/5 transition-all duration-300">
                                 <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:opacity-30 transition-opacity">
                                    <Icon size={40} />
                                 </div>
                                 <div className="bg-cyan-500/10 p-4 rounded-xl mb-4 group-hover:scale-110 transition-transform">
                                     <Icon className="w-8 h-8 text-cyan-400" />
                                 </div>
                                 <h3 className="text-xl font-bold mb-2 tracking-wide">{item.name}</h3>
                                 <p className="text-gray-400 text-xs leading-relaxed mb-6 h-12">{item.description}</p>
                                 <button 
                                    onClick={() => buyItem(item.id as any, item.cost)}
                                    disabled={!canAfford}
                                    className={`px-6 py-3 rounded-lg font-black w-full text-sm tracking-widest transition-all ${canAfford ? 'bg-cyan-500 text-black hover:bg-cyan-400 hover:scale-105 active:scale-95' : 'bg-gray-800 text-gray-500 cursor-not-allowed opacity-40'}`}
                                 >
                                     {item.cost} CREDITS
                                 </button>
                             </div>
                         );
                     })}
                 </div>

                 <button 
                    onClick={closeShop}
                    className="group flex items-center px-12 py-5 bg-white text-black font-black text-xl rounded-full hover:bg-cyan-400 transition-all shadow-xl hover:shadow-cyan-500/20"
                 >
                     RE-ENGAGE <ChevronRight className="ml-2 w-6 h-6 group-hover:translate-x-1 transition-transform" />
                 </button>
             </div>
        </div>
    );
};

export const HUD: React.FC = () => {
  const { score, lives, maxLives, collectedLetters, status, level, restartGame, startGame, gemsCollected, distance, isImmortalityActive, speed } = useStore();
  const target = ['H', 'S', 'G', 'R', 'U', 'N'];

  const containerClass = "absolute inset-0 pointer-events-none flex flex-col justify-between p-6 md:p-12 z-50";

  if (status === GameStatus.SHOP) {
      return <ShopScreen />;
  }

  if (status === GameStatus.MENU) {
      return (
          <div className="absolute inset-0 flex items-center justify-center z-[100] bg-[#050011] overflow-hidden pointer-events-auto">
              <div className="scanline"></div>

              {/* Background Glows */}
              <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-cyan-600/10 rounded-full blur-[120px] animate-pulse"></div>
              <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-600/10 rounded-full blur-[120px] animate-pulse delay-700"></div>

              <div className="relative flex flex-col items-center max-w-2xl w-full p-8 text-center animate-in fade-in zoom-in duration-1000">

                <div className="mb-2 text-cyan-400 font-cyber text-xs md:text-sm tracking-[0.5em] opacity-80 uppercase">
                    NEON SYNTHWAVE ODYSSEY
                </div>

                <div className="relative mb-12">
                    <h1 className="text-6xl md:text-9xl font-title font-black italic tracking-tighter text-white glitch leading-none">
                        HSG<br/><span className="text-cyan-400">RUNNER</span>
                    </h1>
                </div>

                <div className="flex flex-col items-center w-full max-w-sm space-y-4">
                    <button 
                      onClick={() => { audio.init(); startGame(); }}
                      className="w-full relative py-5 bg-white text-black font-black text-2xl uppercase tracking-tighter btn-cyber-glow hover:bg-cyan-400 hover:scale-105 active:scale-95 transition-all duration-300 overflow-hidden group"
                    >
                        <span className="relative z-10 flex items-center justify-center italic">
                            INITIALIZE RUN <Play className="ml-3 w-6 h-6 fill-black" />
                        </span>
                        <div className="absolute inset-0 bg-gradient-to-r from-cyan-400/20 to-purple-400/20 translate-y-full group-hover:translate-y-0 transition-transform"></div>
                    </button>

                    <div className="flex justify-between w-full text-[10px] font-mono text-white/30 tracking-widest uppercase py-2 border-y border-white/5">
                        <span>SYSTEM: ONLINE</span>
                        <span>v3.1.0-ALPHA</span>
                        <span>PING: 12MS</span>
                    </div>
                </div>

                <div className="mt-12 grid grid-cols-2 gap-8 text-white/50 font-cyber text-[10px] uppercase tracking-widest">
                    <div className="flex flex-col items-center">
                        <span className="mb-2 text-cyan-400/50">STEER</span>
                        <div className="p-2 border border-white/10 rounded">ARROWS / SWIPE</div>
                    </div>
                    <div className="flex flex-col items-center">
                        <span className="mb-2 text-cyan-400/50">JUMP</span>
                        <div className="p-2 border border-white/10 rounded">SPACE / UP</div>
                    </div>
                </div>
              </div>
          </div>
      );
  }

  if (status === GameStatus.GAME_OVER) {
      return (
          <div className="absolute inset-0 bg-[#050011]/95 z-[100] text-white pointer-events-auto backdrop-blur-md flex items-center justify-center font-cyber">
              <div className="flex flex-col items-center w-full max-w-lg p-12 bg-black/40 border border-white/5 rounded-[40px] shadow-2xl animate-in zoom-in duration-300">
                <div className="bg-red-500/20 p-6 rounded-full mb-6">
                    <Activity className="w-12 h-12 text-red-500" />
                </div>
                <h1 className="text-5xl md:text-7xl font-black text-white mb-2 tracking-tighter italic">CRITICAL<br/><span className="text-red-600">ERROR</span></h1>
                <p className="text-white/40 text-sm mb-10 tracking-widest">MISSION PARAMETERS COMPROMISED</p>

                <div className="grid grid-cols-2 gap-4 w-full mb-10">
                    <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex flex-col">
                        <span className="text-[10px] text-white/30 mb-1 uppercase">Distance</span>
                        <span className="text-2xl font-bold text-cyan-400 italic">{Math.floor(distance)} LY</span>
                    </div>
                    <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex flex-col">
                        <span className="text-[10px] text-white/30 mb-1 uppercase">Gems</span>
                        <span className="text-2xl font-bold text-yellow-400 italic">{gemsCollected}</span>
