              </div>
          </div>
      );
  }

  if (status === GameStatus.VICTORY) {
    return (
        <div className="absolute inset-0 bg-gradient-to-br from-cyan-900/40 via-purple-900/40 to-[#050011] z-[100] text-white pointer-events-auto backdrop-blur-2xl flex items-center justify-center font-cyber">
            <div className="flex flex-col items-center w-full max-w-xl p-12 text-center animate-in slide-in-from-bottom duration-700">
