                <p className="text-cyan-400/60 text-lg mb-12 tracking-[0.3em] font-mono">CONGRATULATIONS RUNNER</p>

                <div className="bg-white/5 backdrop-blur-md p-8 rounded-[32px] border border-white/10 w-full mb-10">
                    <div className="text-[10px] text-white/40 mb-2 uppercase tracking-widest">Final Data Yield</div>
                    <div className="text-5xl font-black text-white italic tracking-tighter">{score.toLocaleString()}</div>
                    <div className="h-px bg-white/10 my-6"></div>
                    <div className="flex justify-around">
                        <div className="flex flex-col">
                            <span className="text-xs text-white/40 uppercase mb-1 font-mono">Distance</span>
