                <div className="text-[10px] text-cyan-400/70 font-cyber tracking-widest mt-1 uppercase">DATA_STREAM</div>
            </div>

            <div className="flex flex-col items-end">
                <div className="flex space-x-2 mb-2">
                    {[...Array(maxLives)].map((_, i) => (
                        <div 
                            key={i} 
                            className={`w-3 h-3 md:w-5 md:h-5 rotate-45 border-2 ${i < lives ? 'bg-pink-500 border-pink-400' : 'bg-transparent border-gray-700'} transition-all duration-300 shadow-[0_0_10px_rgba(236,72,153,0.3)]`} 
                        />
                    ))}
                </div>
                <div className="text-[10px] text-pink-500/70 font-cyber tracking-widest uppercase italic">HULL_INTEGRITY</div>
            </div>
        </div>

        {/* Center Indicators */}
        <div className="absolute top-10 left-1/2 transform -translate-x-1/2 flex flex-col items-center">
            <div className="text-xs md:text-sm text-cyan-300 font-cyber font-bold tracking-[0.4em] bg-white/5 border border-white/10 px-6 py-2 rounded-full backdrop-blur-md mb-8">
                SECTOR {level}
            </div>

            <div className="flex space-x-2 md:space-x-4">
                {target.map((char, idx) => {
                    const isCollected = collectedLetters.includes(idx);
                    const color = GEMINI_COLORS[idx];

                    return (
                        <div 
                            key={idx}
                            style={{
                                borderColor: isCollected ? color : 'rgba(255, 255, 255, 0.05)',
                                color: isCollected ? '#000' : 'rgba(255, 255, 255, 0.1)',
                                boxShadow: isCollected ? `0 0 25px ${color}` : 'none',
                                backgroundColor: isCollected ? color : 'rgba(0, 0, 0, 0.4)'
                            }}
                            className={`w-8 h-10 md:w-12 md:h-14 flex items-center justify-center border-2 font-black text-xl md:text-2xl italic font-cyber rounded-lg transition-all duration-500 ${isCollected ? 'scale-110' : 'scale-100'}`}
                        >
                            {char}
                        </div>
                    );
                })}
            </div>
        </div>

        {isImmortalityActive && (
             <div className="absolute top-48 left-1/2 transform -translate-x-1/2 text-white font-black text-2xl italic tracking-tighter animate-pulse flex items-center bg-cyan-500 px-6 py-2 rounded-lg shadow-[0_0_30px_rgba(6,182,212,0.6)]">
                 <Shield className="mr-2 fill-white" /> PHASE_SHIFT_ACTIVE
             </div>
        )}

        {/* Bottom Details */}
        <div className="w-full flex justify-between items-end relative z-10">
             <div className="flex flex-col text-white/30 font-cyber text-[10px] uppercase tracking-widest">
                 <div className="flex items-center space-x-2">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span>
                    <span>MISSION_STATUS: ACTIVE</span>
                 </div>
                 <div>COORDINATES: {Math.round(distance)}LY / TARGET_ZENITH</div>
             </div>

             <div className="flex items-center space-x-3 bg-white/5 px-4 py-2 rounded-lg border border-white/10">
                 <Zap className="w-4 h-4 text-yellow-400 animate-bounce" />
                 <span className="font-cyber font-black text-sm md:text-xl italic text-white">THRUST {Math.round((speed / RUN_SPEED_BASE) * 100)}%</span>
             </div>
        </div>
    </div>
  );
};

