import React, { useRef, useEffect, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { useStore } from '../../store';
import { LANE_WIDTH, GameStatus, CHARACTERS } from '../../types';
import { audio } from '../System/Audio';

const GRAVITY = 50;
const JUMP_FORCE = 16; 

const TORSO_GEO = new THREE.CylinderGeometry(0.25, 0.15, 0.6, 4);
const JETPACK_GEO = new THREE.BoxGeometry(0.3, 0.4, 0.15);
const GLOW_STRIP_GEO = new THREE.PlaneGeometry(0.05, 0.2);
const HEAD_GEO = new THREE.BoxGeometry(0.25, 0.3, 0.3);
const ARM_GEO = new THREE.BoxGeometry(0.12, 0.6, 0.12);
const JOINT_SPHERE_GEO = new THREE.SphereGeometry(0.07);
const HIPS_GEO = new THREE.CylinderGeometry(0.16, 0.16, 0.2);
const LEG_GEO = new THREE.BoxGeometry(0.15, 0.7, 0.15);
const SHADOW_GEO = new THREE.CircleGeometry(0.5, 32);

// New Gear Geometries
const WING_GEO = new THREE.BoxGeometry(0.05, 1.2, 0.4);
const CAPE_GEO = new THREE.BoxGeometry(0.5, 1.0, 0.05);
const SPIKE_GEO = new THREE.ConeGeometry(0.1, 0.25, 4);

export const Player: React.FC = () => {
  const groupRef = useRef<THREE.Group>(null);
  const bodyRef = useRef<THREE.Group>(null);
  const shadowRef = useRef<THREE.Mesh>(null);

  const leftArmRef = useRef<THREE.Group>(null);
  const rightArmRef = useRef<THREE.Group>(null);
  const leftLegRef = useRef<THREE.Group>(null);
  const rightLegRef = useRef<THREE.Group>(null);
  const gearRef = useRef<THREE.Group>(null);

  const { status, laneCount, takeDamage, hasDoubleJump, activateImmortality, isImmortalityActive, selectedCharacterId } = useStore();

  const [lane, setLane] = React.useState(0);
  const targetX = useRef(0);
  const isJumping = useRef(false);
  const velocityY = useRef(0);
  const jumpsPerformed = useRef(0); 
  const spinRotation = useRef(0);
  const touchStartX = useRef(0);
  const touchStartY = useRef(0);
  const isInvincible = useRef(false);
  const lastDamageTime = useRef(0);

  const char = useMemo(() => CHARACTERS.find(c => c.id === selectedCharacterId) || CHARACTERS[0], [selectedCharacterId]);

  const { armorMaterial, jointMaterial, glowMaterial, shadowMaterial, gearMaterial } = useMemo(() => {
      const armorColor = isImmortalityActive ? '#ffd700' : char.color;
      const glowColor = isImmortalityActive ? '#ffffff' : char.glow;

      return {
          armorMaterial: new THREE.MeshStandardMaterial({ color: armorColor, roughness: 0.1, metalness: 0.9 }),
          jointMaterial: new THREE.MeshStandardMaterial({ color: '#111111', roughness: 0.7, metalness: 0.5 }),
          glowMaterial: new THREE.MeshBasicMaterial({ color: glowColor }),
          gearMaterial: new THREE.MeshStandardMaterial({ color: char.glow, emissive: char.glow, emissiveIntensity: 2.0, transparent: true, opacity: 0.7 }),
          shadowMaterial: new THREE.MeshBasicMaterial({ color: '#000000', opacity: 0.3, transparent: true })
      };
  }, [isImmortalityActive, char]);

  useEffect(() => {
      if (status === GameStatus.PLAYING) {
          isJumping.current = false;
          jumpsPerformed.current = 0;
          velocityY.current = 0;
          spinRotation.current = 0;
          if (groupRef.current) groupRef.current.position.y = 0;
          if (bodyRef.current) bodyRef.current.rotation.x = 0;
      }
  }, [status]);

  useEffect(() => {
      const maxLane = Math.floor(laneCount / 2);
      if (Math.abs(lane) > maxLane) {
          setLane(l => Math.max(Math.min(l, maxLane), -maxLane));
      }
  }, [laneCount, lane]);

  const triggerJump = () => {
    const maxJumps = hasDoubleJump ? 2 : 1;
    if (!isJumping.current) {
        audio.playJump(false);
        isJumping.current = true;
        jumpsPerformed.current = 1;
        velocityY.current = JUMP_FORCE;
    } else if (jumpsPerformed.current < maxJumps) {
        audio.playJump(true);
        jumpsPerformed.current += 1;
        velocityY.current = JUMP_FORCE;
        spinRotation.current = 0; 
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (status !== GameStatus.PLAYING) return;
      const maxLane = Math.floor(laneCount / 2);
      if (e.key === 'ArrowLeft') setLane(l => Math.max(l - 1, -maxLane));
      else if (e.key === 'ArrowRight') setLane(l => Math.min(l + 1, maxLane));
      else if (e.key === 'ArrowUp' || e.key === 'w') triggerJump();
      else if (e.key === ' ' || e.key === 'Enter') activateImmortality();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [status, laneCount, hasDoubleJump, activateImmortality]);

  useFrame((state, delta) => {
    if (!groupRef.current) return;
    if (status !== GameStatus.PLAYING && status !== GameStatus.SHOP && status !== GameStatus.MENU) return;

    if (status === GameStatus.MENU) {
        groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 2) * 0.1;
        groupRef.current.rotation.y += delta * 0.5;
        groupRef.current.position.x = 0;
        return;
    } else {
        groupRef.current.rotation.y = 0;
    }

    targetX.current = lane * LANE_WIDTH;
    groupRef.current.position.x = THREE.MathUtils.lerp(groupRef.current.position.x, targetX.current, delta * 15);

    if (isJumping.current) {
        groupRef.current.position.y += velocityY.current * delta;
        velocityY.current -= GRAVITY * delta;
        if (groupRef.current.position.y <= 0) {
            groupRef.current.position.y = 0;
            isJumping.current = false;
            jumpsPerformed.current = 0;
            velocityY.current = 0;
            if (bodyRef.current) bodyRef.current.rotation.x = 0;
        }
    }

    const time = state.clock.elapsedTime * 25; 
    if (!isJumping.current) {
        if (leftArmRef.current) leftArmRef.current.rotation.x = Math.sin(time) * 0.7;
        if (rightArmRef.current) rightArmRef.current.rotation.x = Math.sin(time + Math.PI) * 0.7;
        if (leftLegRef.current) leftLegRef.current.rotation.x = Math.sin(time + Math.PI) * 1.0;
        if (rightLegRef.current) rightLegRef.current.rotation.x = Math.sin(time) * 1.0;
        if (bodyRef.current) bodyRef.current.position.y = 1.1 + Math.abs(Math.sin(time)) * 0.1;
    }

    // Animate Gear
    if (gearRef.current) {
        if (char.gearType === 'WINGS') {
            gearRef.current.children.forEach((child, i) => {
                const wingTime = state.clock.elapsedTime * (isJumping.current ? 15 : 5);
                child.rotation.z = (i === 0 ? -0.8 : 0.8) + Math.sin(wingTime) * 0.3;
            });
        } else if (char.gearType === 'CAPE') {
            gearRef.current.rotation.x = 0.5 + Math.sin(state.clock.elapsedTime * 10) * 0.2;
        }
    }

    if (shadowRef.current) {
        const height = groupRef.current.position.y;
        const scale = Math.max(0.2, 1 - (height / 2.5) * 0.5); 
        shadowRef.current.scale.set(scale, scale, scale);
    }
  });

  return (
    <group ref={groupRef}>
      <group ref={bodyRef} position={[0, 1.1, 0]}> 
        <mesh castShadow geometry={TORSO_GEO} material={armorMaterial} position={[0, 0.2, 0]} />
        <mesh geometry={JETPACK_GEO} material={jointMaterial} position={[0, 0.2, -0.2]} />

        {/* CHARACTER GEAR SYSTEM */}
        <group ref={gearRef} position={[0, 0.4, -0.2]}>
            {char.gearType === 'WINGS' && (
                <>
                    <mesh geometry={WING_GEO} material={gearMaterial} position={[0.4, 0, 0]} rotation={[0, 0, 0.8]} />
                    <mesh geometry={WING_GEO} material={gearMaterial} position={[-0.4, 0, 0]} rotation={[0, 0, -0.8]} />
                </>
            )}
            {char.gearType === 'CAPE' && (
                <mesh geometry={CAPE_GEO} material={gearMaterial} position={[0, -0.5, -0.1]} rotation={[0.4, 0, 0]} />
            )}
            {char.gearType === 'VOID' && (
                <mesh scale={[1.2, 1.2, 1.2]} geometry={new THREE.IcosahedronGeometry(0.5, 1)}>
                    <meshBasicMaterial color={char.glow} wireframe transparent opacity={0.2} />
                </mesh>
            )}
        </group>

        <group position={[0, 0.6, 0]}>
            <mesh castShadow geometry={HEAD_GEO} material={armorMaterial} />
            <mesh position={[0, 0, 0.16]} geometry={new THREE.BoxGeometry(0.2, 0.05, 0.05)} material={glowMaterial} />
        </group>

        <group ref={rightArmRef} position={[0.32, 0.4, 0]}>
            <mesh position={[0, -0.25, 0]} geometry={ARM_GEO} material={armorMaterial} />
        </group>
        <group ref={leftArmRef} position={[-0.32, 0.4, 0]}>
            <mesh position={[0, -0.25, 0]} geometry={ARM_GEO} material={armorMaterial} />
        </group>

        <mesh geometry={HIPS_GEO} material={jointMaterial} position={[0, -0.15, 0]} />

        <group ref={rightLegRef} position={[0.12, -0.25, 0]}>
            <mesh position={[0, -0.35, 0]} geometry={LEG_GEO} material={armorMaterial} />
        </group>
        <group ref={leftLegRef} position={[-0.12, -0.25, 0]}>
            <mesh position={[0, -0.35, 0]} geometry={LEG_GEO} material={armorMaterial} />
        </group>
      </group>
      <mesh ref={shadowRef} position={[0, 0.02, 0]} rotation={[-Math.PI/2, 0, 0]} geometry={SHADOW_GEO} material={shadowMaterial} />
    </group>
  );
};

