import { create } from 'zustand';
import { GameStatus, RUN_SPEED_BASE, CHARACTERS, HSG_TARGET } from './types';

interface GameState {
  status: GameStatus;
  score: number;
  lives: number;
  maxLives: number;
  speed: number;
  collectedLetters: number[]; 
  level: number;
  laneCount: number;
  gemsCollected: number;
  distance: number;
  selectedCharacterId: string;
  unlockedCharacterIds: string[];

  // Inventory / Abilities
  hasDoubleJump: boolean;
  hasImmortality: boolean;
  isImmortalityActive: boolean;

  // Actions
  startGame: () => void;
  restartGame: () => void;
  takeDamage: () => void;
  addScore: (amount: number) => void;
  collectGem: (value: number) => void;
  collectLetter: (index: number) => void;
  setStatus: (status: GameStatus) => void;
  setDistance: (dist: number) => void;
  setSelectedCharacter: (id: string) => void;
  unlockCharacter: (id: string, cost: number) => boolean;
  skipLevel: (cost: number) => boolean;

  // Shop / Abilities
  buyItem: (type: string, cost: number) => boolean;
  advanceLevel: () => void;
  openShop: () => void;
  closeShop: () => void;
  activateImmortality: () => void;
}

const MAX_LEVEL = 3;

export const useStore = create<GameState>((set, get) => ({
  status: GameStatus.MENU,
  score: 0,
  lives: 3,
  maxLives: 3,
  speed: 0,
  collectedLetters: [],
  level: 1,
  laneCount: 3,
  gemsCollected: 0,
  distance: 0,
  selectedCharacterId: CHARACTERS[0].id,
  unlockedCharacterIds: [CHARACTERS[0].id],

  hasDoubleJump: false,
  hasImmortality: false,
  isImmortalityActive: false,

  startGame: () => set({ 
    status: GameStatus.PLAYING, 
    score: 0, 
    lives: 3, 
    maxLives: 3,
    speed: RUN_SPEED_BASE,
    collectedLetters: [],
    level: 1,
    laneCount: 3,
    gemsCollected: 0,
    distance: 0,
    hasDoubleJump: false,
    hasImmortality: false,
    isImmortalityActive: false
  }),

  restartGame: () => set({ 
    status: GameStatus.PLAYING, 
    score: 0, 
    lives: 3, 
    maxLives: 3,
    speed: RUN_SPEED_BASE,
    collectedLetters: [],
    level: 1,
    laneCount: 3,
    gemsCollected: 0,
    distance: 0,
    hasDoubleJump: false,
    hasImmortality: false,
    isImmortalityActive: false
  }),

  takeDamage: () => {
    const { lives, isImmortalityActive } = get();
    if (isImmortalityActive) return;

    if (lives > 1) {
      set({ lives: lives - 1 });
    } else {
      set({ lives: 0, status: GameStatus.GAME_OVER, speed: 0 });
    }
  },

  addScore: (amount) => set((state) => ({ score: state.score + amount })),

  collectGem: (value) => set((state) => ({ 
    score: state.score + value, 
    gemsCollected: state.gemsCollected + 1 
  })),

  setDistance: (dist) => set({ distance: dist }),

  setSelectedCharacter: (id) => set({ selectedCharacterId: id }),

  unlockCharacter: (id, cost) => {
    const { score, unlockedCharacterIds } = get();
    if (score >= cost && !unlockedCharacterIds.includes(id)) {
        set({
            score: score - cost,
            unlockedCharacterIds: [...unlockedCharacterIds, id],
            selectedCharacterId: id
        });
        return true;
    }
    return false;
  },

  skipLevel: (cost) => {
    const { score, level } = get();
    if (score >= cost && level < MAX_LEVEL) {
        set({ score: score - cost });
        get().advanceLevel();
        get().closeShop();
        return true;
    }
    return false;
  },

  collectLetter: (index) => {
    const { collectedLetters, level } = get();

    if (!collectedLetters.includes(index)) {
      const newLetters = [...collectedLetters, index];
      set({ collectedLetters: newLetters });

      if (newLetters.length === HSG_TARGET.length) {
        if (level < MAX_LEVEL) {
            get().advanceLevel();
        } else {
            set({
                status: GameStatus.VICTORY,
                score: get().score + 5000
            });
        }
      }
    }
  },

  advanceLevel: () => {
      const { level, laneCount, speed } = get();
      const nextLevel = level + 1;
      const newSpeed = speed + (RUN_SPEED_BASE * 0.40);

      set({
          level: nextLevel,
          laneCount: Math.min(laneCount + 2, 9),
          status: GameStatus.PLAYING,
          speed: newSpeed,
          collectedLetters: []
      });
  },

  openShop: () => set({ status: GameStatus.SHOP }),
  closeShop: () => set({ status: GameStatus.PLAYING }),

  buyItem: (type, cost) => {
      const { score, maxLives, lives } = get();
      if (score < cost) return false;

      set({ score: score - cost });
      switch (type) {
          case 'DOUBLE_JUMP': set({ hasDoubleJump: true }); break;
          case 'MAX_LIFE': set({ maxLives: maxLives + 1, lives: lives + 1 }); break;
          case 'HEAL': set({ lives: Math.min(lives + 1, maxLives) }); break;
          case 'IMMORTAL': set({ hasImmortality: true }); break;
          case 'SKIP': get().skipLevel(0); break; // Cost already handled
      }
      return true;
  },

  activateImmortality: () => {
      const { hasImmortality, isImmortalityActive } = get();
      if (hasImmortality && !isImmortalityActive) {
          set({ isImmortalityActive: true });
          setTimeout(() => set({ isImmortalityActive: false }), 5000);
      }
  },

  setStatus: (status) => set({ status }),
}));

