import React, { useRef, useEffect, useState, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { Text3D, Center } from '@react-three/drei';
import { v4 as uuidv4 } from 'uuid';
import { useStore } from '../../store';
import { GameObject, ObjectType, LANE_WIDTH, SPAWN_DISTANCE, REMOVE_DISTANCE, GameStatus, GEMINI_COLORS, HSG_TARGET } from '../../types';
import { audio } from '../System/Audio';

const OBSTACLE_HEIGHT = 1.6;
const OBSTACLE_GEOMETRY = new THREE.ConeGeometry(0.9, OBSTACLE_HEIGHT, 6);
const GEM_GEOMETRY = new THREE.IcosahedronGeometry(0.3, 0);
const FONT_URL = "https://cdn.jsdelivr.net/npm/three/examples/fonts/helvetiker_bold.typeface.json";
const PARTICLE_COUNT = 300;

const ParticleSystem: React.FC = () => {
    const mesh = useRef<THREE.InstancedMesh>(null);
    const dummy = useMemo(() => new THREE.Object3D(), []);
    const particles = useMemo(() => new Array(PARTICLE_COUNT).fill(0).map(() => ({
        life: 0, pos: new THREE.Vector3(), vel: new THREE.Vector3(), color: new THREE.Color()
    })), []);

    useEffect(() => {
        const handleExplosion = (e: any) => {
            const { position, color } = e.detail;
            let count = 0;
            for(let i = 0; i < PARTICLE_COUNT; i++) {
                if (particles[i].life <= 0) {
                    particles[i].life = 1.0;
                    particles[i].pos.set(position[0], position[1], position[2]);
                    particles[i].vel.set((Math.random()-0.5)*15, Math.random()*15, (Math.random()-0.5)*15);
                    particles[i].color.set(color);
                    if (++count > 25) break;
                }
            }
        };
        window.addEventListener('particle-burst', handleExplosion);
        return () => window.removeEventListener('particle-burst', handleExplosion);
    }, [particles]);

    useFrame((_, delta) => {
        if (!mesh.current) return;
        particles.forEach((p, i) => {
            if (p.life > 0) {
                p.life -= delta * 1.5;
                p.pos.addScaledVector(p.vel, delta);
                p.vel.y -= delta * 12; // Gravity
                dummy.position.copy(p.pos);
                dummy.scale.setScalar(p.life * 0.3);
                dummy.updateMatrix();
                mesh.current!.setMatrixAt(i, dummy.matrix);
                mesh.current!.setColorAt(i, p.color);
            } else {
                dummy.scale.setScalar(0);
                dummy.updateMatrix();
                mesh.current!.setMatrixAt(i, dummy.matrix);
            }
        });
        mesh.current.instanceMatrix.needsUpdate = true;
        if (mesh.current.instanceColor) mesh.current.instanceColor.needsUpdate = true;
    });

    return (
        <instancedMesh ref={mesh} args={[undefined, undefined, PARTICLE_COUNT]}>
            <boxGeometry args={[0.3, 0.3, 0.3]} />
            <meshBasicMaterial toneMapped={false} />
        </instancedMesh>
    );
};

export const LevelManager: React.FC = () => {
  const { status, speed, collectGem, collectLetter, collectedLetters, laneCount, openShop, level } = useStore();
  const objectsRef = useRef<GameObject[]>([]);
  const [renderTrigger, setRenderTrigger] = useState(0);
  const playerGroupRef = useRef<THREE.Object3D | null>(null);
  const distanceTraveled = useRef(0);
  const nextLetterDistance = useRef(150);

  useEffect(() => {
    if (status === GameStatus.MENU || status === GameStatus.GAME_OVER || status === GameStatus.VICTORY) {
        objectsRef.current = [];
        distanceTraveled.current = 0;
        nextLetterDistance.current = 150;
        setRenderTrigger(t => t + 1);
    }
  }, [status]);

  useFrame((state, delta) => {
    if (status !== GameStatus.PLAYING) return;

    if (!playerGroupRef.current) {
        playerGroupRef.current = state.scene.getObjectByName('PlayerGroup');
    }

    const dist = speed * delta;
    distanceTraveled.current += dist;

    // Fallback if playerGroup lookup fails
    const playerPos = new THREE.Vector3();
    if (playerGroupRef.current) {
        playerGroupRef.current.getWorldPosition(playerPos);
    } else {
        // Assume player is roughly at Z=0 if search fails, though x/y might be wrong
        playerPos.set(0, 0, 0); 
    }

    let hasChanges = false;
    const keptObjects: GameObject[] = [];

    for (const obj of objectsRef.current) {
        obj.position[2] += dist;
        let keep = obj.position[2] < REMOVE_DISTANCE;

        // Collision logic
        if (obj.active && Math.abs(obj.position[2] - playerPos.z) < 1.0) {
            const dx = Math.abs(obj.position[0] - playerPos.x);
            if (dx < 0.9) {
                if (obj.type === ObjectType.OBSTACLE) {
                    // Obstacle hit check
                    if (playerPos.y < OBSTACLE_HEIGHT) {
                        window.dispatchEvent(new Event('player-hit'));
                        obj.active = false;
                        hasChanges = true;
                    }
                } else if (obj.type === ObjectType.GEM) {
                    collectGem(50);
                    audio.playGemCollect();
                    obj.active = false;
                    hasChanges = true;
                    window.dispatchEvent(new CustomEvent('particle-burst', { detail: { position: obj.position, color: '#00ffff' } }));
                } else if (obj.type === ObjectType.LETTER) {
                    collectLetter(obj.targetIndex!);
                    audio.playLetterCollect();
                    obj.active = false;
                    hasChanges = true;
                    window.dispatchEvent(new CustomEvent('particle-burst', { detail: { position: obj.position, color: obj.color } }));
                }
            }
        }
        if (keep) keptObjects.push(obj);
    }

    // Spawn New Objects
    let furthestZ = keptObjects.length ? Math.min(...keptObjects.map(o => o.position[2])) : 0;
    if (furthestZ > -SPAWN_DISTANCE) {
        const spawnZ = furthestZ - (18 + speed * 0.2);
        const lane = Math.floor(Math.random() * laneCount) - Math.floor(laneCount/2);

        // Letter spawning
        if (distanceTraveled.current >= nextLetterDistance.current) {
            const neededIdx = HSG_TARGET.map((_, i) => i).filter(i => !collectedLetters.includes(i));
            if (neededIdx.length > 0) {
                const idx = neededIdx[0];
                keptObjects.push({
                    id: uuidv4(), type: ObjectType.LETTER, position: [lane * LANE_WIDTH, 1.2, spawnZ], active: true,
                    value: HSG_TARGET[idx], color: GEMINI_COLORS[idx % GEMINI_COLORS.length], targetIndex: idx
                });
                nextLetterDistance.current += 150;
                hasChanges = true;
            }
        } else {
            // General objects
            const rand = Math.random();
            if (rand < 0.7) { // Obstacle
                keptObjects.push({
                    id: uuidv4(), type: ObjectType.OBSTACLE, position: [lane * LANE_WIDTH, OBSTACLE_HEIGHT/2, spawnZ], active: true, color: '#ff0055'
                });
            } else { // Gem
                keptObjects.push({
                    id: uuidv4(), type: ObjectType.GEM, position: [lane * LANE_WIDTH, 1.2, spawnZ], active: true, color: '#00ffff'
                });
            }
            hasChanges = true;
        }
    }

    if (hasChanges) {
        objectsRef.current = keptObjects;
        setRenderTrigger(t => t + 1);
    }
  });

  return (
    <group>
        <ParticleSystem />
        {objectsRef.current.map(obj => (
            obj.active && (
                <group key={obj.id} position={[obj.position[0], obj.position[1], obj.position[2]]}>
                    {obj.type === ObjectType.OBSTACLE && (
                        <mesh geometry={OBSTACLE_GEOMETRY}>
                            <meshStandardMaterial color={obj.color} emissive={obj.color} emissiveIntensity={0.5} roughness={0.1} metalness={0.9} />
                        </mesh>
                    )}
                    {obj.type === ObjectType.GEM && (
                        <mesh geometry={GEM_GEOMETRY} rotation={[Math.random(), Math.random(), Math.random()]}>
                            <meshStandardMaterial color={obj.color} emissive={obj.color} emissiveIntensity={3} />
                        </mesh>
                    )}
                    {obj.type === ObjectType.LETTER && (
                        <Center scale={1.2}>
                            <Text3D font={FONT_URL} size={0.8} height={0.25} curveSegments={12}>
                                {obj.value}
                                <meshStandardMaterial color={obj.color} emissive={obj.color} emissiveIntensity={2} />
                            </Text3D>
                        </Center>
                    )}
                </group>
            )
        ))}
    </group>
  );
};

