import { audio } from '../System/Audio';

const SHOP_ITEMS: ShopItem[] = [
    { id: 'HEAL', name: 'NANO-REPAIR', description: 'Restores 1 core unit.', cost: 800, icon: PlusCircle },
    { id: 'DOUBLE_JUMP', name: 'BOOST DRIVE', description: 'Secondary aerial thrust.', cost: 1200, icon: ArrowUpCircle, oneTime: true },
    { id: 'IMMORTAL', name: 'VOID SHIELD', description: '5s phase intangibility.', cost: 2000, icon: Shield, oneTime: true },
    { id: 'MAX_LIFE', name: 'HULL CORE', description: 'Permanent HP expansion.', cost: 3000, icon: Activity },
    { id: 'SKIP', name: 'HYPER-WARP', description: 'Bypass current sector.', cost: 5000, icon: FastForward, special: true }
];

const LifeUnit: React.FC<{ active: boolean; wasLost: boolean }> = ({ active, wasLost }) => (
    <div className="relative w-6 h-6 md:w-8 md:h-8 flex items-center justify-center">
        <div className={`absolute inset-0 border-2 border-white/10 rounded-lg rotate-45 transition-all duration-500 ${active ? 'bg-pink-500/30' : 'bg-black/60'}`} />
        {active && !wasLost && <Heart className="relative z-10 w-4 h-4 md:w-5 md:h-5 fill-pink-500 text-pink-400 animate-heart-pulse" />}
        {wasLost && <Heart className="relative z-20 w-4 h-4 md:w-5 md:h-5 fill-red-600 text-white animate-heart-shatter" />}
    </div>
);

export const HUD: React.FC = () => {
  const { 
    score, lives, maxLives, collectedLetters, status, level, 
    restartGame, startGame, gemsCollected, distance, 
    isImmortalityActive, speed, selectedCharacterId, 
    setSelectedCharacter, unlockedCharacterIds, unlockCharacter, buyItem, closeShop
  } = useStore();

  const [charIndex, setCharIndex] = useState(0);
  const [lostLifeIndex, setLostLifeIndex] = useState<number | null>(null);
  const prevLivesRef = useRef(lives);

  useEffect(() => {
    if (lives < prevLivesRef.current) {
        setLostLifeIndex(lives);
        setTimeout(() => setLostLifeIndex(null), 1000);
    }
    prevLivesRef.current = lives;
  }, [lives]);

  const MenuWrapper = ({ children }: { children: React.ReactNode }) => (
      <div className="absolute inset-0 flex flex-col items-center justify-between z-[100] bg-black/20 pointer-events-auto backdrop-blur-[2px] p-6 md:p-12 font-cyber overflow-hidden">
          <div className="scanline"></div>
          {children}
      </div>
  );

  if (status === GameStatus.SHOP) {
      return (
          <MenuWrapper>
              <div className="w-full flex justify-between items-center animate-in fade-in slide-in-from-top">
                  <div className="flex items-center space-x-3">
                      <ShoppingCart className="text-cyan-400 w-8 h-8 md:w-10 md:h-10" />
                      <h2 className="text-3xl md:text-5xl font-black italic tracking-tighter">CYBER<span className="text-cyan-400">FORGE</span></h2>
                  </div>
                  <div className="flex items-center space-x-4 bg-white/5 px-6 py-3 rounded-2xl border border-white/10 backdrop-blur-xl">
                      <Diamond className="text-yellow-400 w-6 h-6" />
                      <span className="text-3xl font-black text-white">{score.toLocaleString()}</span>
                  </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-4 w-full max-w-7xl animate-in zoom-in duration-500">
                  {SHOP_ITEMS.map(item => {
                      const canAfford = score >= item.cost;
                      const Icon = item.icon;
                      return (
                          <div key={item.id} className={`p-6 border-2 rounded-3xl transition-all flex flex-col items-center text-center bg-black/80 backdrop-blur-md relative overflow-hidden group ${item.special ? 'border-yellow-500/40 shadow-[0_0_20px_rgba(234,179,8,0.15)]' : 'border-white/10 hover:border-cyan-400/50'}`}>
                              <div className="absolute top-0 right-0 p-2 opacity-5"><Icon size={64} /></div>
                              <Icon className={`w-12 h-12 mb-4 ${item.special ? 'text-yellow-400' : 'text-cyan-400'} group-hover:scale-110 transition-transform`} />
                              <h3 className="text-lg font-black mb-1 uppercase tracking-tight leading-none">{item.name}</h3>
                              <p className="text-white/40 text-[10px] mb-8 leading-tight h-8 flex items-center">{item.description}</p>
                              <button 
                                onClick={() => buyItem(item.id, item.cost)}
                                disabled={!canAfford}
                                className={`w-full py-4 rounded-xl font-black text-xs tracking-[0.2em] transition-all ${canAfford ? 'bg-white text-black hover:bg-cyan-400 active:scale-95' : 'bg-white/5 text-white/20'}`}
                              >
                                  {item.cost.toLocaleString()} CR
                              </button>
                          </div>
                      );
                  })}
              </div>

              <button 
                onClick={closeShop} 
                className="group flex items-center space-x-3 px-16 py-6 bg-cyan-400 text-black font-black text-2xl italic tracking-tighter rounded-full hover:bg-white hover:scale-110 transition-all shadow-[0_0_40px_rgba(34,211,238,0.3)]"
              >
                  <span>RE-ENGAGE</span> <ChevronRight className="group-hover:translate-x-1 transition-transform" />
              </button>
          </MenuWrapper>
      );
  }

  if (status === GameStatus.MENU) {
      const char = CHARACTERS[charIndex];
      const isUnlocked = unlockedCharacterIds.includes(char.id);
      return (
          <MenuWrapper>
              <div className="w-full flex justify-between items-start animate-in fade-in slide-in-from-top">
                  <div className="flex flex-col">
                    <h1 className="text-5xl md:text-8xl font-title font-black italic text-white glitch leading-none">HSG<span className="text-cyan-400">RUN</span></h1>
