                  >
                    <ChevronLeft size={48} />
                  </button>

                  <div 
                    style={{ 
                        boxShadow: isUnlocked ? `0 0 100px ${char.glow}22` : 'none', 
                        borderColor: isUnlocked ? char.color : 'rgba(255,255,255,0.1)' 
