                    className="bg-black/60 border-2 rounded-[60px] p-10 md:p-14 w-full max-w-md flex flex-col items-center transition-all animate-in zoom-in duration-500 backdrop-blur-3xl relative group"
                  >
                      <div 
                        className={`w-32 h-32 md:w-44 md:h-44 rounded-[40px] flex items-center justify-center mb-10 transition-all duration-700 relative ${isUnlocked ? 'scale-110' : 'grayscale opacity-30 scale-95'}`} 
                        style={{ backgroundColor: `${char.color}11`, border: `2px solid ${char.color}55` }}
                      >
                          <UserCheck size={96} style={{ color: char.color }} />
                          {isUnlocked && <div className="absolute inset-0 rounded-[40px] animate-ping opacity-20" style={{ backgroundColor: char.color }}></div>}
                      </div>

                      <h3 className="text-4xl md:text-5xl font-black italic mb-2 uppercase text-center tracking-tighter" style={{ color: char.color }}>{char.name}</h3>
                      <p className="text-xs text-white/40 mb-12 tracking-[0.3em] text-center uppercase font-bold px-6">{char.description}</p>

                      <div className="w-full">
                        {isUnlocked ? (
                            <button 
                                onClick={() => { setSelectedCharacter(char.id); audio.init(); startGame(); }} 
                                className="w-full py-6 bg-white text-black font-black text-2xl italic tracking-tighter rounded-3xl hover:bg-cyan-400 hover:scale-105 active:scale-95 transition-all flex items-center justify-center shadow-2xl"
                            >
                                DEPLOY UNIT <Play className="ml-3 fill-black" />
                            </button>
                        ) : (
                            <button 
                                onClick={() => unlockCharacter(char.id, char.cost)} 
                                disabled={score < char.cost} 
                                className={`w-full py-6 rounded-3xl flex flex-col items-center transition-all ${score >= char.cost ? 'bg-yellow-500 text-black hover:bg-yellow-400 hover:scale-105 active:scale-95 shadow-xl shadow-yellow-500/20' : 'bg-white/5 text-white/10 cursor-not-allowed'}`}
                            >
                                <div className="flex items-center text-2xl font-black italic tracking-tighter">
                                    <Lock className="mr-2 w-6 h-6" /> ACQUIRE UNIT
                                </div>
                                <div className="text-xs font-bold tracking-widest">{char.cost.toLocaleString()} CREDITS</div>
                            </button>
                        )}
                      </div>
                  </div>

                  <button 
                    onClick={() => setCharIndex((charIndex + 1) % CHARACTERS.length)} 
                    className="p-6 bg-white/5 hover:bg-white/10 border border-white/5 rounded-full text-white/50 hover:text-white transition-all shadow-xl"
                  >
                    <ChevronRight size={48} />
                  </button>
              </div>

              <div className="flex flex-col items-center animate-in slide-in-from-bottom duration-1000">
                  <div className="flex space-x-4 mb-6">
                      {CHARACTERS.map((c, i) => (
                          <div 
                            key={c.id} 
                            onClick={() => setCharIndex(i)}
                            className={`h-2 rounded-full transition-all duration-500 cursor-pointer ${i === charIndex ? 'w-16 bg-white' : 'w-3 bg-white/20 hover:bg-white/40'}`} 
                          />
                      ))}
                  </div>
                  <div className="text-[10px] text-white/10 tracking-[0.8em] uppercase font-bold">NEON_SYNTH_CORE_V5</div>
              </div>
          </MenuWrapper>
      );
  }

  if (status === GameStatus.GAME_OVER || status === GameStatus.VICTORY) {
      const isWin = status === GameStatus.VICTORY;
      return (
          <MenuWrapper>
               <div className="flex-1 flex flex-col items-center justify-center max-w-2xl w-full animate-in zoom-in duration-500">
                    <div className={`p-10 rounded-full mb-10 relative ${isWin ? 'bg-cyan-500/10' : 'bg-red-500/10'}`}>
                        <div className={`absolute inset-0 rounded-full blur-3xl opacity-20 ${isWin ? 'bg-cyan-400' : 'bg-red-500'}`}></div>
                        {isWin ? <Trophy className="w-20 h-20 text-cyan-400 relative z-10" /> : <Activity className="w-20 h-20 text-red-500 relative z-10" />}
                    </div>
                    <h2 className="text-6xl md:text-8xl font-black italic tracking-tighter mb-4 text-center leading-none">
                        {isWin ? 'MISSION<br/>SUCCESS' : 'MISSION<br/>FAILED'}
                    </h2>
                    <p className="text-white/40 text-sm tracking-[0.4em] mb-12 text-center uppercase font-bold">
                        {isWin ? 'ZENITH REACHED RUNNER' : 'SYSTEM CRITICAL ERROR'}
                    </p>

                    <div className="grid grid-cols-2 gap-4 w-full max-w-md mb-12">
                         <div className="bg-white/5 p-6 rounded-3xl border border-white/5 flex flex-col items-center">
                             <span className="text-xs text-white/30 uppercase mb-2 tracking-widest font-bold">Net Yield</span>
                             <span className="text-4xl font-black text-white italic tracking-tighter">{score.toLocaleString()}</span>
                         </div>
                         <div className="bg-white/5 p-6 rounded-3xl border border-white/5 flex flex-col items-center">
                             <span className="text-xs text-white/30 uppercase mb-2 tracking-widest font-bold">Sector</span>
                             <span className="text-4xl font-black text-cyan-400 italic tracking-tighter">{level}</span>
                         </div>
                    </div>

                    <button 
                      onClick={() => { audio.init(); restartGame(); }}
                      className={`w-full max-w-md py-8 font-black text-3xl italic tracking-tighter rounded-3xl transition-all hover:scale-105 active:scale-95 shadow-2xl ${isWin ? 'bg-cyan-400 text-black' : 'bg-white text-black hover:bg-red-500'}`}
                    >
                        RE-INITIALIZE
                    </button>
               </div>
          </MenuWrapper>
      );
  }

  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-8 md:p-14 z-50 font-cyber">
        <div className="flex justify-between items-start w-full relative z-10">
            <div className="flex flex-col">
                <div className="text-5xl md:text-7xl font-black text-white italic tracking-tighter leading-none drop-shadow-2xl">{score.toLocaleString()}</div>
                <div className="text-xs text-cyan-400/80 tracking-[0.5em] mt-2 uppercase font-black">CREDITS_STREAM</div>
            </div>
            <div className="flex items-center space-x-4 bg-black/40 p-4 md:p-5 rounded-3xl border border-white/10 backdrop-blur-xl">
                {[...Array(maxLives)].map((_, i) => (
                    <LifeUnit key={i} active={i < lives} wasLost={i === lostLifeIndex} />
                ))}
            </div>
        </div>

        <div className="absolute top-10 left-1/2 transform -translate-x-1/2 flex flex-col items-center">
            <div className="bg-white/10 backdrop-blur-2xl px-12 py-3 rounded-full border border-white/10 text-cyan-400 text-sm tracking-[0.6em] mb-12 uppercase font-black shadow-xl">SECTOR {level}</div>
            <div className="flex space-x-3 md:space-x-5">
                {HSG_TARGET.map((char, idx) => {
                    const isCollected = collectedLetters.includes(idx);
                    const color = GEMINI_COLORS[idx % GEMINI_COLORS.length];
                    return (
                        <div key={idx} style={{ 
                            borderColor: isCollected ? color : 'rgba(255,255,255,0.05)', 
                            color: isCollected ? '#000' : 'rgba(255,255,255,0.1)', 
                            backgroundColor: isCollected ? color : 'rgba(0,0,0,0.6)', 
                            boxShadow: isCollected ? `0 0 30px ${color}` : 'none' 
                        }} className={`w-10 h-14 md:w-14 md:h-20 flex items-center justify-center border-2 font-black text-2xl md:text-3xl italic rounded-2xl transition-all duration-500 ${isCollected ? 'scale-110 rotate-3 translate-y-[-5px]' : ''}`}>
                            {char}
                        </div>
                    );
                })}
            </div>
        </div>

        {isImmortalityActive && (
             <div className="absolute top-64 left-1/2 transform -translate-x-1/2 text-white font-black text-2xl italic tracking-tighter animate-pulse flex items-center bg-cyan-600/80 px-10 py-4 rounded-2xl shadow-[0_0_60px_rgba(8,145,178,0.7)] border-2 border-cyan-300 backdrop-blur-md">
                 <Shield className="mr-4 w-8 h-8 fill-white" /> PHASE_SHIFT_ACTIVE
             </div>
        )}

        <div className="w-full flex justify-between items-end relative z-10">
             <div className="text-[11px] text-white/30 tracking-[0.5em] font-bold bg-black/30 px-6 py-3 rounded-xl border border-white/5 backdrop-blur-md">
                COORD_X: {Math.round(distance)} LY
             </div>
             <div className="flex items-center space-x-4 bg-white/5 px-8 py-4 rounded-2xl border border-white/10 backdrop-blur-2xl shadow-xl">
                 <Zap className={`w-6 h-6 text-yellow-400 ${speed > 25 ? 'animate-bounce' : ''}`} />
                 <span className="text-2xl md:text-4xl font-black italic text-white tracking-tighter">
                    {Math.round((speed / RUN_SPEED_BASE) * 100)}%
                 </span>
             </div>
        </div>
    </div>
  );
};

